import sys

def main():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    max_len = 0
    dp = [0] * n

    for i in range(n):
        dp[i] = 1
        for j in range(i):
            if s[j:i+1] in s[:j] and len(s[j:i+1]) < len(s[j+1:i+1]) if j+1 <= i else True:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
        max_len = max(max_len, dp[i])

    print(max_len)

